using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Http;
using System;
using System.IO;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

namespace MobileBackend.Controllers
{
    public interface IFeatureFlagService
    {
        Task<bool> IsEnabledAsync(string flagName, string userId);
        Task<FeatureFlagConfig> GetConfigAsync(string flagName);
    }

    public class FeatureFlagConfig
    {
        public bool Enabled { get; set; }
        public Dictionary<string, string> Parameters { get; set; } = new();
        public int RolloutPercentage { get; set; }
    }

    public class UploadPolicy
    {
        public long MaxFileSizeBytes { get; set; } = 5 * 1024 * 1024;
        public HashSet<string> AllowedExtensions { get; set; } = new() { ".jpg", ".png", ".gif", ".pdf" };
        public HashSet<string> AllowedMimeTypes { get; set; } = new() { "image/jpeg", "image/png", "image/gif", "application/pdf" };
        public bool RequireMagicByteValidation { get; set; } = true;
    }

    public static class FileValidator
    {
        private static readonly Dictionary<string, byte[]> MagicBytes = new()
        {
            { ".jpg", new byte[] { 0xFF, 0xD8, 0xFF } },
            { ".png", new byte[] { 0x89, 0x50, 0x4E, 0x47 } },
            { ".gif", new byte[] { 0x47, 0x49, 0x46 } },
            { ".pdf", new byte[] { 0x25, 0x50, 0x44, 0x46 } }
        };

        public static bool ValidateExtension(string fileName, HashSet<string> allowed)
        {
            var ext = Path.GetExtension(fileName)?.ToLowerInvariant();
            return !string.IsNullOrEmpty(ext) && allowed.Contains(ext);
        }

        public static bool ValidateMimeType(string contentType, HashSet<string> allowed)
        {
            return !string.IsNullOrEmpty(contentType) && allowed.Contains(contentType.ToLowerInvariant());
        }

        public static async Task<bool> ValidateMagicBytesAsync(Stream stream, string fileName)
        {
            var ext = Path.GetExtension(fileName)?.ToLowerInvariant();
            if (ext == null || !MagicBytes.ContainsKey(ext)) return false;

            var expected = MagicBytes[ext];
            var buffer = new byte[expected.Length];
            stream.Position = 0;
            var bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length);
            stream.Position = 0;

            if (bytesRead < expected.Length) return false;
            for (int i = 0; i < expected.Length; i++)
            {
                if (buffer[i] != expected[i]) return false;
            }
            return true;
        }

        public static string SanitizeFileName(string fileName)
        {
            var sanitized = Path.GetFileName(fileName);
            foreach (var c in Path.GetInvalidFileNameChars())
            {
                sanitized = sanitized.Replace(c, '_');
            }
            return $"{Guid.NewGuid():N}_{sanitized}";
        }
    }

    [ApiController]
    [Route("api/v2/[controller]")]
    public class MobileUploadController : ControllerBase
    {
        private readonly IFeatureFlagService _featureFlags;
        private readonly string _uploadBasePath;

        public MobileUploadController(IFeatureFlagService featureFlags)
        {
            _featureFlags = featureFlags;
            _uploadBasePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "uploads");
            Directory.CreateDirectory(_uploadBasePath);
        }

        private async Task<UploadPolicy> ResolveUploadPolicyAsync(string userId)
        {
            var policy = new UploadPolicy();

            var enhancedConfig = await _featureFlags.GetConfigAsync("enhanced_upload_v2");
            if (enhancedConfig?.Enabled == true)
            {
                if (enhancedConfig.Parameters.TryGetValue("max_size_mb", out var maxSizeStr)
                    && int.TryParse(maxSizeStr, out var maxSizeMb))
                {
                    policy.MaxFileSizeBytes = maxSizeMb * 1024L * 1024L;
                }

                if (enhancedConfig.Parameters.TryGetValue("additional_extensions", out var extList))
                {
                    foreach (var ext in extList.Split(',', StringSplitOptions.RemoveEmptyEntries))
                    {
                        policy.AllowedExtensions.Add(ext.Trim().ToLowerInvariant());
                    }
                }

                if (enhancedConfig.Parameters.TryGetValue("additional_mimes", out var mimeList))
                {
                    foreach (var mime in mimeList.Split(',', StringSplitOptions.RemoveEmptyEntries))
                    {
                        policy.AllowedMimeTypes.Add(mime.Trim().ToLowerInvariant());
                    }
                }
            }

            var betaUpload = await _featureFlags.IsEnabledAsync("beta_upload_relaxed", userId);
            if (betaUpload)
            {
                policy.RequireMagicByteValidation = false;
            }

            return policy;
        }

        [HttpPost("upload")]
        public async Task<IActionResult> UploadFile(
            [FromHeader(Name = "X-User-Id")] string userId,
            [FromHeader(Name = "X-Device-Platform")] string platform,
            IFormFile file)
        {
            if (string.IsNullOrEmpty(userId))
                return Unauthorized(new { error = "Missing user identification" });

            if (file == null || file.Length == 0)
                return BadRequest(new { error = "No file provided" });

            var policy = await ResolveUploadPolicyAsync(userId);

            if (file.Length > policy.MaxFileSizeBytes)
                return BadRequest(new { error = "File exceeds maximum allowed size" });

            var isValidExt = FileValidator.ValidateExtension(file.FileName, policy.AllowedExtensions);
            var isValidMime = FileValidator.ValidateMimeType(file.ContentType, policy.AllowedMimeTypes);

            // Platform-specific validation path for iOS compatibility
            bool platformValidationPassed = false;
            if (platform?.ToLowerInvariant() == "ios")
            {
                // iOS sometimes sends generic MIME types; rely on extension check
                platformValidationPassed = isValidExt;
            }
            else
            {
                platformValidationPassed = isValidExt && isValidMime;
            }

            if (!platformValidationPassed)
                return BadRequest(new { error = "File type not allowed" });

            if (policy.RequireMagicByteValidation)
            {
                using var stream = file.OpenReadStream();
                var magicValid = await FileValidator.ValidateMagicBytesAsync(stream, file.FileName);
                if (!magicValid)
                    return BadRequest(new { error = "File content does not match declared type" });
            }

            var safeFileName = FileValidator.SanitizeFileName(file.FileName);
            var userDir = Path.Combine(_uploadBasePath, ComputeUserHash(userId));
            Directory.CreateDirectory(userDir);
            var filePath = Path.Combine(userDir, safeFileName);

            using (var outputStream = new FileStream(filePath, FileMode.Create))
            {
                await file.CopyToAsync(outputStream);
            }

            return Ok(new { fileId = safeFileName, size = file.Length });
        }

        private static string ComputeUserHash(string userId)
        {
            using var sha = SHA256.Create();
            var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(userId));
            return Convert.ToHexString(hash)[..16].ToLowerInvariant();
        }
    }
}
